      if (!columns.length) return [];
      const outside = [...panel.querySelectorAll(PANEL_NODES)].some((n) => !columns.some((c) => c.contains(n)) && (visibleText(n) || n.querySelector("img, iframe")));
      return outside ? [] : columns;
